from __future__ import annotations


TEMPLATE_PATH = 'backend/app/api/dependencies.py'
TEMPLATE_CONTENT = 'from fastapi import Depends, HTTPException\nfrom fastapi.security import HTTPAuthorizationCredentials, HTTPBearer\nfrom jose import JWTError\nfrom sqlalchemy import select\nfrom sqlalchemy.ext.asyncio import AsyncSession\n\nfrom app.core.database import get_db\nfrom app.core.security import decode_access_token\nfrom app.models.membership import Membership\nfrom app.services.audit_service import create_audit_log\n\n\nsecurity = HTTPBearer()\n\n\nasync def get_current_user_id(\n    credentials: HTTPAuthorizationCredentials = Depends(security),\n) -> str:\n    token = credentials.credentials\n\n    try:\n        payload = decode_access_token(token)\n        user_id = payload.get("sub")\n\n        if not user_id:\n            raise HTTPException(status_code=401, detail="Invalid token")\n\n        return user_id\n\n    except JWTError:\n        raise HTTPException(status_code=401, detail="Invalid token")\n\n\nasync def get_current_user(\n    current_user_id: str = Depends(get_current_user_id),\n):\n    return {\n        "id": current_user_id,\n    }\n\n\ndef require_role(allowed_roles: list[str]):\n    async def role_checker(\n        current_user_id: str = Depends(get_current_user_id),\n        db: AsyncSession = Depends(get_db),\n    ):\n        try:\n            user_id = int(current_user_id)\n        except ValueError:\n            raise HTTPException(status_code=401, detail="Invalid token subject")\n\n        result = await db.execute(\n            select(Membership).where(\n                Membership.user_id == user_id,\n                Membership.role.in_(allowed_roles),\n            )\n        )\n        membership = result.scalar_one_or_none()\n\n        if membership is None:\n            await create_audit_log(\n                db=db,\n                event_type="rbac_denied",\n                status="blocked",\n                actor_user_id=user_id,\n                detail=f"Insufficient role. allowed_roles={allowed_roles}",\n            )\n            raise HTTPException(status_code=403, detail="Insufficient role")\n\n        return True\n\n    return role_checker\n'
